import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('starts with duplicate retry knowledge and user-owned integration files', async () => {
  const domain = await readFile(new URL('../.agents/knowledge/domains/payments.md', import.meta.url), 'utf8');
  const pattern = await readFile(new URL('../.agents/knowledge/patterns/retry.md', import.meta.url), 'utf8');
  const rule = await readFile(new URL('../.agents/rules/payments.md', import.meta.url), 'utf8');
  const hook = await readFile(new URL('../.agents/hooks/custom.sh', import.meta.url), 'utf8');
  assert.match(domain, /three times/);
  assert.match(pattern, /three attempts/);
  assert.match(rule, /payments knowledge/);
  assert.match(hook, /user-owned-audit-hook/);
});
